() => {
  const hero = document.querySelector('section, div');
  // Find the hero container by heading text
  const h1 = [...document.querySelectorAll('h1')].find(h=>/Generate CSS/.test(h.textContent));
  let heroSection = h1;
  while (heroSection && heroSection.parentElement && heroSection.parentElement.tagName !== 'BODY') {
    heroSection = heroSection.parentElement;
  }
  return {
    heroTag: heroSection.tagName,
    heroClass: heroSection.className,
    heroOuterStart: heroSection.outerHTML.slice(0,600),
    nextSibling: heroSection.nextElementSibling ? heroSection.nextElementSibling.className : null,
    bodyChildren: [...document.body.children].map(c=>c.tagName+'.'+c.className)
  };
}

