  return {
    viewport: window.innerWidth,
    formDisplay: getComputedStyle(form).flexDirection,
    sameRow: Math.abs(ir.top - br.top) < 5,
    inputRight: Math.round(ir.right), btnLeft: Math.round(br.left),
    inputWidth: Math.round(ir.width), btnWidth: Math.round(br.width)
  };
}

